-- Name: access_override_company_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_override_company_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM user_company_roles ucr
     WHERE ucr.user_id = NEW.user_id AND ucr.company_id = NEW.company_id
  ) THEN
    RAISE EXCEPTION 'ACCESS_OVERRIDE_COMPANY_ROLE_REQUIRED' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


