-- Name: FUNCTION erp_audit_log_append_only(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.erp_audit_log_append_only() IS '2026-10-audit-log-append-only-v3';


--
-- Name: erp_audit_log_before_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_audit_log_before_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
   DECLARE
     v_prev text;
   BEGIN
     NEW.request_id := COALESCE(NEW.request_id, NULLIF(btrim(current_setting('app.request_id', true)), ''));
     NEW.ip := COALESCE(NEW.ip, NULLIF(btrim(current_setting('app.request_ip', true)), ''));
     NEW.session_id := COALESCE(NEW.session_id, NULLIF(btrim(current_setting('app.session_hash', true)), ''));
     NEW.reason := COALESCE(NEW.reason, NULLIF(btrim(current_setting('app.audit_reason', true)), ''));
     NEW.prev_hash := NULL;
     IF erp_audit_log_is_financial(NEW.table_name) THEN
       SELECT a.row_hash INTO v_prev FROM audit_log a
        WHERE a.prev_hash IS NOT NULL AND a.id < NEW.id
        ORDER BY a.id DESC LIMIT 1;
       NEW.prev_hash := COALESCE(v_prev, 'genesis');
     END IF;
     NEW.row_hash := erp_audit_log_row_hash(NEW);
     RETURN NEW;
   END
   $$;


--
-- Name: erp_audit_log_is_financial(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_audit_log_is_financial(audit_table text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
     SELECT NOT (lower(btrim(COALESCE(audit_table, ''))) = ANY (ARRAY['remote_support_sessions', 'reports', 'location_whatsapp_stock_reports', 'location_whatsapp_stock_deliveries', 'location_whatsapp_stock_schedules']::text[]))
   $$;


--
-- Name: erp_audit_log_no_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_audit_log_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
   BEGIN
     RAISE EXCEPTION USING ERRCODE = '42501',
       MESSAGE = 'AUDIT_LOG_APPEND_ONLY: audit_log cannot be truncated; the audit trail is append-only';
   END
   $$;


SET LOCAL default_tablespace = '';

SET LOCAL default_table_access_method = heap;

--
-- Name: audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_log (
    action text NOT NULL,
    after_data text,
    before_data text,
    changes jsonb,
    company_id integer,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    entity_id integer,
    entity_type text,
    id integer NOT NULL,
    ip text,
    ip_address text,
    prev_hash text,
    reason text,
    record_id integer,
    record_identifier text,
    request_id text,
    row_hash text,
    session_id text,
    table_name text NOT NULL,
    user_id character varying NOT NULL,
    username text NOT NULL
);


--
-- Name: erp_audit_log_row_hash(public.audit_log); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_audit_log_row_hash(r public.audit_log) RETURNS text
    LANGUAGE sql STABLE
    AS $$
     SELECT encode(sha256(convert_to(jsonb_build_array(
              r.id, r.user_id, r.username, r.company_id, r.action, r.table_name, r.record_id,
              r.record_identifier, r.changes, to_char(r.created_at, 'YYYY-MM-DD"T"HH24:MI:SS.US'),
              r.request_id, r.ip, r.session_id, r.reason, r.prev_hash)::text, 'UTF8')), 'hex')
   $$;


--
-- Name: erp_authorized_company_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_authorized_company_ids() RETURNS integer[]
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  raw_company_ids text;
  parsed_company_ids integer[];
BEGIN
  raw_company_ids := current_setting('app.authorized_company_ids', true);
  IF raw_company_ids IS NULL OR btrim(raw_company_ids) = '' THEN
    RETURN ARRAY[]::integer[];
  END IF;

  BEGIN
    parsed_company_ids := string_to_array(raw_company_ids, ',')::integer[];
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'app.authorized_company_ids must be a comma-separated list of positive integers';
  END;

  IF EXISTS (SELECT 1 FROM unnest(parsed_company_ids) AS company_id WHERE company_id <= 0) THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'app.authorized_company_ids must contain only positive integers';
  END IF;

  RETURN parsed_company_ids;
END
$$;


--
-- Name: erp_bank_account_delete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_bank_account_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
   DECLARE
     balance numeric;
   BEGIN
     IF erp_ledger_integrity_bypassed() OR NEW.deleted_at IS NULL OR OLD.deleted_at IS NOT NULL THEN
       RETURN NEW;
     END IF;
     SELECT (CASE WHEN OLD.opening_balance_side = 'Cr' THEN -1 ELSE 1 END) * COALESCE(OLD.opening_balance, 0)
            + COALESCE(SUM(ve.debit_amount - ve.credit_amount), 0)
       INTO balance
       FROM voucher_entries ve JOIN vouchers v ON v.id = ve.voucher_id
      WHERE ve.bank_account_id = OLD.id AND ve.ledger_account_id IS NULL
        AND v.deleted_at IS NULL AND v.optional = false;
     IF balance <> 0 THEN
       RAISE EXCEPTION USING ERRCODE = '23514',
         MESSAGE = format('BANK_ACCOUNT_HAS_BALANCE: bank account %s has a balance of %s and cannot be deleted', OLD.id, balance),
         HINT = 'Move its balance to another account with a journal entry first, or deactivate it instead.';
     END IF;
     RETURN NEW;
   END
   $$;


