--
-- Name: resolve_factory_product_french_snapshot(integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_factory_product_french_snapshot(p_company_id integer, p_product_id integer, p_article_code text) RETURNS TABLE(product_name_fr text, category_fr text)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    COALESCE(NULLIF(BTRIM(p.name_fr), ''), NULLIF(BTRIM(p.name), ''), NULLIF(BTRIM(p.name_ar), ''), NULLIF(BTRIM(p.article_code), '')),
    COALESCE(NULLIF(BTRIM(c.name_fr), ''), NULLIF(BTRIM(c.name), ''), NULLIF(BTRIM(c.name_ar), ''), NULLIF(BTRIM(p.article_code), ''))
  FROM factory_bale_products p
  LEFT JOIN factory_categories c
    ON c.id = p.category_id
   AND c.company_id = p.company_id
   AND c.deleted_at IS NULL
  WHERE p.company_id = p_company_id
    AND p.deleted_at IS NULL
    AND (
      (p_product_id IS NOT NULL AND p.id = p_product_id)
      OR (
        p_product_id IS NULL
        AND p_article_code IS NOT NULL
        AND UPPER(BTRIM(p.article_code)) = UPPER(BTRIM(p_article_code))
      )
    )
  ORDER BY CASE WHEN p.id = p_product_id THEN 0 ELSE 1 END
  LIMIT 1;
$$;


--
-- Name: retail_snapshot_sale_item_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retail_snapshot_sale_item_cost() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  resolved_cost numeric(20,6);
BEGIN

  SELECT cost
  INTO resolved_cost
  FROM retail_product_variants
  WHERE id = NEW.variant_id
    AND company_id = NEW.company_id;

  IF resolved_cost IS NULL THEN
    RAISE EXCEPTION
      'Retail variant % does not belong to company %',
      NEW.variant_id,
      NEW.company_id;
  END IF;

  NEW.unit_cost := resolved_cost;

  RETURN NEW;
END;
$$;


--
-- Name: rotate_user_credential_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_user_credential_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF NEW.password IS DISTINCT FROM OLD.password THEN
    INSERT INTO user_credential_versions(user_id, credential_version, updated_at)
    VALUES (NEW.id, 1, now())
    ON CONFLICT (user_id) DO UPDATE
      SET credential_version = user_credential_versions.credential_version + 1,
          updated_at = now();

    IF to_regclass('public.session') IS NOT NULL THEN
      EXECUTE 'DELETE FROM session WHERE sess->>''userId'' = $1' USING NEW.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: set_customer_order_bale_scanned_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_order_bale_scanned_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      DECLARE
        restored_at TIMESTAMPTZ;
        restored_match BOOLEAN := FALSE;
        history_has_scanned_at BOOLEAN := FALSE;
      BEGIN
        IF NEW.scanned_at IS NOT NULL THEN
          RETURN NEW;
        END IF;

        IF to_regclass('public.customer_order_bales_history') IS NOT NULL THEN
          SELECT EXISTS (
            SELECT 1
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = 'customer_order_bales_history'
              AND column_name = 'scanned_at'
          ) INTO history_has_scanned_at;

          IF history_has_scanned_at THEN
            SELECT h.scanned_at, TRUE
            INTO restored_at, restored_match
            FROM public.customer_order_bales_history h
            WHERE h.order_id = NEW.order_id
              AND h.bale_id = NEW.bale_id
            ORDER BY h.cancelled_at DESC
            LIMIT 1;

            IF restored_match THEN
              NEW.scanned_at := restored_at;
              RETURN NEW;
            END IF;
          END IF;
        END IF;

        IF NEW.scanned_by IS NOT NULL AND btrim(NEW.scanned_by) <> '' THEN
          NEW.scanned_at := CURRENT_TIMESTAMP;
        END IF;
        RETURN NEW;
      END;
      $$;


