--
-- Name: sto_wa_workbook_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sto_wa_workbook_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
 BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Approved workbook evidence cannot be deleted'; END IF;
  IF NEW.company_id IS DISTINCT FROM OLD.company_id
     OR NEW.batch_id IS DISTINCT FROM OLD.batch_id
     OR NEW.snapshot_json IS DISTINCT FROM OLD.snapshot_json
     OR NEW.snapshot_sha256 IS DISTINCT FROM OLD.snapshot_sha256
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (OLD.workbook_bytes IS NOT NULL AND
       (NEW.workbook_bytes IS DISTINCT FROM OLD.workbook_bytes
        OR NEW.workbook_sha256 IS DISTINCT FROM OLD.workbook_sha256
        OR NEW.filename IS DISTINCT FROM OLD.filename
        OR NEW.rendered_at IS DISTINCT FROM OLD.rendered_at))
  THEN RAISE EXCEPTION 'Approved workbook snapshot is immutable'; END IF;
  RETURN NEW;
 END $$;


--
-- Name: stock_transfer_revision_link_superseded_after_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_revision_link_superseded_after_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
     BEGIN
       IF NEW.status = 'pending' AND NEW.created_by IS NOT NULL THEN
         UPDATE stock_transfer_revisions
         SET superseded_by_revision_id = NEW.id
         WHERE transfer_id = NEW.transfer_id
           AND created_by = NEW.created_by
           AND id <> NEW.id
           AND status = 'superseded'
           AND superseded_by_revision_id IS NULL
           AND reviewed_by = NEW.created_by
           AND reviewed_at = transaction_timestamp();
       END IF;
       RETURN NEW;
     END
     $$;


--
-- Name: stock_transfer_revision_supersede_before_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_revision_supersede_before_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
     BEGIN
       IF NEW.status = 'pending' AND NEW.created_by IS NOT NULL THEN
         UPDATE stock_transfer_revisions
         SET
           status = 'superseded',
           optional = false,
           reviewed_at = transaction_timestamp(),
           reviewed_by = NEW.created_by,
           superseded_by_revision_id = NULL
         WHERE transfer_id = NEW.transfer_id
           AND created_by = NEW.created_by
           AND status = 'pending';
       END IF;
       RETURN NEW;
     END
     $$;


