--
-- Name: sync_sp_container_supplier_to_voucher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_sp_container_supplier_to_voucher() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
          BEGIN
            IF NEW.goods_otw_voucher_id IS NULL THEN
              RETURN NEW;
            END IF;

            IF TG_OP = 'INSERT' OR NEW.goods_otw_voucher_id IS DISTINCT FROM OLD.goods_otw_voucher_id THEN
              -- Linking: fill an empty header supplier only.
              UPDATE vouchers
              SET supplier_id = NEW.supplier_id
              WHERE id = NEW.goods_otw_voucher_id
                AND company_id = NEW.company_id
                AND supplier_id IS NULL
                AND NEW.supplier_id IS NOT NULL;
            ELSIF NEW.supplier_id IS DISTINCT FROM OLD.supplier_id THEN
              -- Supplier change: only a voucher that is not posted follows it.
              UPDATE vouchers
              SET supplier_id = NEW.supplier_id
              WHERE id = NEW.goods_otw_voucher_id
                AND company_id = NEW.company_id
                AND optional = true
                AND deleted_at IS NULL
                AND supplier_id IS DISTINCT FROM NEW.supplier_id;

              UPDATE voucher_entries ve
              SET supplier_id = NEW.supplier_id
              FROM ledger_accounts la, vouchers v
              WHERE ve.voucher_id = NEW.goods_otw_voucher_id
                AND v.id = ve.voucher_id
                AND v.company_id = NEW.company_id
                AND v.optional = true
                AND v.deleted_at IS NULL
                AND ve.ledger_account_id = la.id
                AND la.company_id = NEW.company_id
                AND la.sub_type = 'sp_otw_clearing'
                AND ve.supplier_id IS DISTINCT FROM NEW.supplier_id;
            END IF;
            RETURN NEW;
          END;
          $$;


--
-- Name: unified_release_review_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unified_release_review_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
 BEGIN
  IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'RELEASE_REVIEW_DELETE_FORBIDDEN' USING ERRCODE='23514';
  END IF;
  IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL
   OR (to_jsonb(NEW)-'revoked_at'-'revoked_by'-'revoke_reason')
      IS DISTINCT FROM
      (to_jsonb(OLD)-'revoked_at'-'revoked_by'-'revoke_reason')
   OR NULLIF(TRIM(COALESCE(NEW.revoked_by,'')),'') IS NULL
   OR LENGTH(TRIM(COALESCE(NEW.revoke_reason,'')))<10
  THEN RAISE EXCEPTION 'RELEASE_REVIEW_IMMUTABLE' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END $$;


