-- Name: bales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bales (
    article_code character varying(50),
    bale_code character varying(50),
    barcode character varying(255) NOT NULL,
    category character varying(255) NOT NULL,
    company_id integer NOT NULL,
    container_id integer,
    cost_per_kg numeric(20,2) DEFAULT 0,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    currency character varying(10) DEFAULT 'USD'::character varying,
    customer_id integer,
    date_pressed date NOT NULL,
    erp_location_id integer,
    finalized_at timestamp without time zone,
    finalized_by integer,
    grade character varying(10) NOT NULL,
    id integer NOT NULL,
    location_id integer,
    mix_batch_id integer,
    origin character varying(10) NOT NULL,
    pressed_at timestamp without time zone,
    pressing_batch_id integer,
    price character varying(50),
    product_id integer,
    product_name text,
    quantity integer DEFAULT 1,
    reference_number character varying(100),
    sold_date date,
    status character varying(20) DEFAULT 'AVAILABLE'::character varying,
    total_cost numeric(20,2) DEFAULT 0,
    updated_at timestamp without time zone DEFAULT now(),
    weight character varying(50) NOT NULL,
    weight_kg numeric(15,3),
    CONSTRAINT bales_grade_check CHECK (((grade)::text = ANY (ARRAY[('A'::character varying)::text, ('B'::character varying)::text, ('C'::character varying)::text]))),
    CONSTRAINT bales_origin_check CHECK (((origin)::text = ANY (ARRAY[('EU'::character varying)::text, ('AUS'::character varying)::text, ('USA'::character varying)::text]))),
    CONSTRAINT bales_status_check CHECK (((status)::text = ANY (ARRAY[('AVAILABLE'::character varying)::text, ('SOLD'::character varying)::text, ('RESERVED'::character varying)::text])))
);


