    CONSTRAINT fd_erp_po_receipt_complete_ck CHECK (((((status)::text = 'PENDING_REVIEW'::text) AND (container_id IS NULL) AND (import_log_id IS NULL) AND (imported_at IS NULL)) OR (((status)::text = 'IMPORTED'::text) AND (container_id IS NOT NULL) AND (import_log_id IS NOT NULL) AND (imported_at IS NOT NULL)))),
    CONSTRAINT fd_erp_po_receipt_fingerprint_ck CHECK ((length((payload_fingerprint)::text) = 64)),
    CONSTRAINT fd_erp_po_receipt_status_ck CHECK (((status)::text = ANY (ARRAY[('PENDING_REVIEW'::character varying)::text, ('IMPORTED'::character varying)::text])))
);

