    wallet_id bigint NOT NULL,
    CONSTRAINT factory_fx_agent_wallet_operations_kind_check CHECK ((kind = ANY (ARRAY['USD_TO_EUR'::text, 'EUR_SETTLEMENT'::text, 'EUR_TO_USD_REVERSAL'::text]))),
