    CONSTRAINT factory_fx_agent_wallet_operations_target_amount_check CHECK ((target_amount > (0)::numeric)),
    CONSTRAINT factory_fx_agent_wallet_operations_target_kind_check CHECK ((target_kind = ANY (ARRAY['factorySupplier'::text, 'supplier'::text, 'ledger'::text]))),
    CONSTRAINT fx_agent_operation_shape CHECK ((((kind = 'USD_TO_EUR'::text) AND ((source_currency)::text = 'USD'::text) AND ((target_currency)::text = 'EUR'::text) AND (target_kind IS NULL) AND (target_id IS NULL) AND (voucher_id IS NULL) AND (reverses_operation_id IS NULL)) OR ((kind = 'EUR_TO_USD_REVERSAL'::text) AND ((source_currency)::text = 'EUR'::text) AND ((target_currency)::text = 'USD'::text) AND (target_kind IS NULL) AND (target_id IS NULL) AND (voucher_id IS NULL) AND (reverses_operation_id IS NOT NULL)) OR ((kind = 'EUR_SETTLEMENT'::text) AND ((source_currency)::text = 'EUR'::text) AND ((((target_currency)::text = 'USD'::text) AND (target_kind = ANY (ARRAY['factorySupplier'::text, 'ledger'::text]))) OR (((target_currency)::text = 'EUR'::text) AND (target_kind = 'factorySupplier'::text))) AND (target_id IS NOT NULL) AND (voucher_id IS NOT NULL) AND (reverses_operation_id IS NULL))))
);


