    chat_id text NOT NULL,
    company_id integer NOT NULL,
    day_of_month integer DEFAULT 1 NOT NULL,
    day_of_week integer DEFAULT 1 NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    frequency text DEFAULT 'monthly'::text NOT NULL,
    period_mode text DEFAULT 'previous_month'::text NOT NULL,
    send_time character varying(5) DEFAULT '09:00'::character varying NOT NULL,
    timezone text DEFAULT 'Asia/Beirut'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT properties_account_wa_schedules_day_of_month_check CHECK (((day_of_month >= 1) AND (day_of_month <= 28))),
    CONSTRAINT properties_account_wa_schedules_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6))),
    CONSTRAINT properties_account_wa_schedules_frequency_check CHECK ((frequency = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text]))),
    CONSTRAINT properties_account_wa_schedules_period_mode_check CHECK ((period_mode = ANY (ARRAY['current_month'::text, 'previous_month'::text]))),
    CONSTRAINT properties_account_wa_schedules_send_time_check CHECK (((send_time)::text ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'::text))
);


