CREATE TABLE public.purchase_orders (
    charges_edited boolean DEFAULT false,
    company_id integer NOT NULL,
    container_id integer NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    discount numeric(20,2) DEFAULT '0'::numeric,
    document_charges numeric(20,2) DEFAULT '0'::numeric,
    freight numeric(20,2) DEFAULT '0'::numeric,
    freight_own_account_id integer,
    freight_paid_by text DEFAULT 'supplier'::text,
    freight_parent_account_id integer,
    fumigation numeric(20,2) DEFAULT '0'::numeric,
    historical_exchange_rate numeric(20,10),
    historical_rate_date date,
    id integer NOT NULL,
    items_total numeric(20,2) DEFAULT '0'::numeric,
    native_discount numeric(20,2),
    native_document_charges numeric(20,2),
    native_freight numeric(20,2),
    native_fumigation numeric(20,2),
    native_items_total numeric(20,2),
    native_line_count integer,
    native_other_charges numeric(20,2),
    native_surcharge numeric(20,2),
    other_charges numeric(20,2) DEFAULT '0'::numeric,
    po_number character varying(100) NOT NULL,
    status text DEFAULT 'Open'::text NOT NULL,
    supplier_id integer NOT NULL,
    surcharge numeric(20,2) DEFAULT '0'::numeric,
    voucher_id integer
);


--
-- Name: purchase_orders_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.purchase_orders_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
