    CONSTRAINT support_tickets_priority_check CHECK (((priority)::text = ANY (ARRAY[('low'::character varying)::text, ('normal'::character varying)::text, ('high'::character varying)::text, ('urgent'::character varying)::text]))),
    CONSTRAINT support_tickets_priority_ck CHECK (((priority)::text = ANY (ARRAY[('low'::character varying)::text, ('normal'::character varying)::text, ('high'::character varying)::text, ('urgent'::character varying)::text]))),
    CONSTRAINT support_tickets_reopened_count_check CHECK ((reopened_count >= 0)),
    CONSTRAINT support_tickets_source_mode_check CHECK (((source_mode)::text = ANY (ARRAY[('erp'::character varying)::text, ('factory'::character varying)::text]))),
    CONSTRAINT support_tickets_status_check CHECK (((status)::text = ANY (ARRAY[('open'::character varying)::text, ('seen'::character varying)::text, ('working'::character varying)::text, ('finalized'::character varying)::text, ('reopened'::character varying)::text]))),
    CONSTRAINT support_tickets_status_ck CHECK (((status)::text = ANY (ARRAY[('open'::character varying)::text, ('seen'::character varying)::text, ('working'::character varying)::text, ('finalized'::character varying)::text, ('reopened'::character varying)::text]))),
    CONSTRAINT support_tickets_version_check CHECK ((version > 0))
);


